/* Introductory hand-range examples, not solver output. */
const ranks='AKQJT98765432'.split('');
const scenarios={
 'open':{title:'ABERTURA · PRIMEIRO A ENTRAR',hint:'Exemplo simplificado: mãos que podem ser consideradas para abrir quando ninguém aumentou antes.',groups:{early:['AA','KK','QQ','JJ','TT','AKs','AQs','AKo'],middle:['AA','KK','QQ','JJ','TT','99','88','AKs','AQs','AJs','KQs','AKo','AQo'],late:['AA','KK','QQ','JJ','TT','99','88','77','66','AKs','AQs','AJs','ATs','KQs','KJs','QJs','JTs','AKo','AQo','AJo','KQo']},action:'ABRIR / RAISE'},
 'call':{title:'CALL · PAGAR UM RAISE',hint:'Exemplo de mãos candidatas a avaliar contra uma abertura. O call depende do tamanho da aposta, posição e adversário.',groups:{early:['QQ','JJ','TT','99','AKs','AQs'],middle:['JJ','TT','99','88','AQs','AJs','KQs'],late:['TT','99','88','77','66','AJs','ATs','KQs','QJs','JTs']},action:'CONSIDERAR CALL'},
 'threebet':{title:'RE-RAISE · 3-BET',hint:'Exemplos de mãos fortes para compreender o aumento sobre uma abertura. Não é uma frequência ótima de 3-bet.',groups:{early:['AA','KK','QQ','AKs','AKo'],middle:['AA','KK','QQ','JJ','AKs','AQs','AKo'],late:['AA','KK','QQ','JJ','TT','AKs','AQs','AJs','AKo','AQo']},action:'CONSIDERAR 3-BET'},
 'shove':{title:'ALL-IN · STACK CURTO',hint:'Apenas exemplos de mãos fortes para estudar um all-in pré-flop. A decisão real depende especialmente do stack efetivo.',groups:{early:['AA','KK','QQ','AKs'],middle:['AA','KK','QQ','JJ','AKs','AKo'],late:['AA','KK','QQ','JJ','TT','AKs','AQs','AKo']},action:'ESTUDAR ALL-IN'},
 'callshove':{title:'CALL ALL-IN · PAGAR UM SHOVE',hint:'Exemplos conservadores de mãos fortes. Não use esta seleção como recomendação automática para pagar all-in.',groups:{early:['AA','KK'],middle:['AA','KK','QQ'],late:['AA','KK','QQ','AKs']},action:'AVALIAR CALL ALL-IN'}
};
const groupFor=pos=>['UTG','UTG+1','MP','LJ'].includes(pos)?'early':['HJ','CO'].includes(pos)?'middle':'late';
const hand=(i,j)=>i===j?ranks[i]+ranks[j]:i<j?ranks[i]+ranks[j]+'s':ranks[j]+ranks[i]+'o';
export function rangesLibrary(){return `<section class="ranges-library"><details class="ranges-entry"><summary><strong>CONSULTAR RANGES BÁSICOS</strong><span>Filtre situações comuns e visualize as mãos na tabela</span></summary><div class="ranges-library-inner"><p>As tabelas são <strong>exemplos didáticos, não ranges validados por solver</strong>. As decisões reais variam conforme stack, formato, apostas e adversários.</p><div class="ranges-filters"><label>STREET<select id="ranges-street"><option value="pre">PRÉ-FLOP</option><option value="flop">FLOP</option><option value="turn">TURN</option><option value="river">RIVER</option></select></label><label>POSIÇÃO<select id="ranges-position">${['UTG','UTG+1','MP','LJ','HJ','CO','BTN','SB','BB'].map(p=>`<option value="${p}" ${p==='BTN'?'selected':''}>${p}</option>`).join('')}</select></label><label>SITUAÇÃO<select id="ranges-scenario">${Object.entries(scenarios).map(([k,v])=>`<option value="${k}">${v.title}</option>`).join('')}</select></label></div><div class="ranges-output" aria-live="polite"></div><p class="ranges-source">FONTE: EXEMPLOS EDUCACIONAIS · VALIDAÇÃO TEXAS SOLVER / DCFR PENDENTE</p></div></details></section>`}
export function setupRangesLibrary(root){const el=root.querySelector('.ranges-library');if(!el)return;const street=el.querySelector('#ranges-street'),pos=el.querySelector('#ranges-position'),scenario=el.querySelector('#ranges-scenario'),out=el.querySelector('.ranges-output');const update=()=>{const st=street.value,sc=scenarios[scenario.value],position=pos.value;if(st!=='pre'){out.innerHTML=`<h3>${{flop:'FLOP',turn:'TURN',river:'RIVER'}[st]} · ${position}</h3><p>Nas streets pós-flop, os ranges dependem das cartas comunitárias, das apostas anteriores e dos stacks. Observe mãos feitas, projetos e blefes possíveis. Não há tabela fixa confiável sem definir o board e a sequência de ações.</p>`;return}const chosen=new Set(sc.groups[groupFor(position)]);out.innerHTML=`<h3>${sc.title}</h3><p><strong>${position}</strong> · ${sc.hint}</p><div class="ranges-matrix" role="table" aria-label="Tabela educativa de 169 classes de mãos">${ranks.map((_,i)=>ranks.map((_,j)=>{const h=hand(i,j);return `<span role="cell" class="${chosen.has(h)?'range-selected':'range-muted'}" title="${h}">${h}</span>`}).join('')).join('')}</div><div class="ranges-key"><span class="range-key-on"></span> ${sc.action} <span class="range-key-off"></span> FORA DESTE EXEMPLO</div><p>Suited (s): mesmo naipe. Offsuit (o): naipes diferentes. Pares: duas cartas do mesmo valor. Esta tabela não define mãos obrigatórias nem garante lucro.</p>`};[street,pos,scenario].forEach(c=>c.addEventListener('change',update));update()}
